  "challenges": [
    {
      "number": "01",
      "title": "Communication",
      "problem": "Neurologic injury or disease can impair a person's ability to speak, write, or gesture \u2014 isolating patients from loved ones and care teams.",
      "solution": "Developing implantable and non-invasive brain-computer interfaces (BCIs) and neural decoding algorithms that translate neural activity directly into text, synthesized speech, and digital control."
    },
    {
      "number": "02",
      "title": "Mobility",
      "problem": "Paralysis and motor impairment after stroke, spinal cord injury, ALS, or cerebral palsy limit independence and daily function.",
      "solution": "Combining targeted neuromodulation, wearable sensors, neuro-rehabilitation robotics, and motor prosthesis systems to restore voluntary movement and functional independence."
    },
    {
      "number": "03",
      "title": "Seizures",
      "problem": "Millions of patients live with drug-resistant epilepsy and unpredictable seizures that disrupt cognition, safety, and quality of life.",
      "solution": "Advancing high-resolution intracranial neurophysiology, thalamic and cortical network mapping, and closed-loop neurostimulation (RNS, DBS) to predict, prevent, and stop seizures."
    },
    {
      "number": "04",
      "title": "Consciousness",
      "problem": "After severe traumatic or hypoxic-ischemic brain injury, bedside exams frequently miss covert awareness and cannot reliably predict recovery.",
      "solution": "Pioneering stimulus-based fMRI, quantitative EEG, ultra-high-resolution connectomics, and brainstem arousal network stimulation to detect consciousness and awaken the injured brain."
    },
    {
      "number": "05",
      "title": "Cognition & Brain Health",
      "problem": "Neurodegenerative diseases, stroke, epilepsy, and neurotrauma erode memory, executive function, and long-term brain resilience.",
      "solution": "Deploying multimodal biomarkers, sleep neurophysiology, precision medicine, and preventative clinical trials to protect and restore cognitive function across the lifespan."
    }
  ],
