      "name": "Jolie Saint-Cyr",
      "roleGroup": "Research Team Management",
      "jobTitle": "Administrative Assistant",
      "shortDescription": "Administrative Assistant",
      "bio": "Jolie completed her Bachelor's degree in Health Science from the University of Massachusetts, Boston. She plans to attend graduate school in the future. She joined the CNTR Team in April 2022. She is excited to gain knowledge on research of the brain and everything it entails.",
      "photo": "https://static.wixstatic.com/media/e6c040_09f106f25e6b4b38845404f66c97deb4~mv2.jpg",
