      "name": "Pariya Salami, PhD",
      "roleGroup": "Faculty",
      "jobTitle": "Instructor, MGH Department of Neurology",
      "shortDescription": "Instructor, MGH Department of Neurology",
      "bio": "Dr. Pariya Salami is an Instructor in Neurology at Massachusetts General Hospital and Harvard Medical School.",
      "photo": "https://static.wixstatic.com/media/e6c040_856c67061f714e568042e0f17c0b7b30~mv2.png",
