      "name": "William Li, MD",
      "roleGroup": "Research Scientists",
      "jobTitle": "Research Fellow, MGH Ziv Lab",
      "shortDescription": "Research Fellow, MGH Ziv Lab\n\nPsychiatry Resident, Massachusetts General Hospital",
      "bio": "Dr. William Li is a psychiatry resident interested in neural mechanisms underlying group decision making and social constructs. Outside of lab, he enjoys brewing beer, cooking, and exploring the world.",
